-- 039: casino — roulette spins (daily cap), IRL prize raffles (coin tickets), poker tables (state as JSON). Paste as one line in the D1 console.
CREATE TABLE IF NOT EXISTS roulette_spins ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, day TEXT NOT NULL, bet INTEGER NOT NULL, payout INTEGER NOT NULL, result INTEGER NOT NULL, bets TEXT, created_at INTEGER NOT NULL );
CREATE INDEX IF NOT EXISTS idx_roulette_user_day ON roulette_spins (user_id, day);
CREATE TABLE IF NOT EXISTS raffles ( id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, prize TEXT NOT NULL, image TEXT, ticket_price INTEGER NOT NULL, max_per_user INTEGER NOT NULL, draws_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'open', winner_id INTEGER, delivered INTEGER NOT NULL DEFAULT 0, created_by INTEGER, created_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS raffle_tickets ( raffle_id INTEGER NOT NULL REFERENCES raffles(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, n INTEGER NOT NULL, coins INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (raffle_id, user_id) );
CREATE TABLE IF NOT EXISTS poker_tables ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, sb INTEGER NOT NULL, bb INTEGER NOT NULL, min_buyin INTEGER NOT NULL, max_buyin INTEGER NOT NULL, seats INTEGER NOT NULL DEFAULT 6, state TEXT NOT NULL DEFAULT '{}', version INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'open', created_by INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
INSERT INTO poker_tables (name, sb, bb, min_buyin, max_buyin, seats, created_at, updated_at) SELECT 'Mesa Moikas', 5, 10, 100, 1000, 6, strftime('%s','now')*1000, strftime('%s','now')*1000 WHERE NOT EXISTS (SELECT 1 FROM poker_tables);
